"""Mutations of display/components/core/web_json.c, see ../redproof.py."""

F = "components/core/web_json.c"
H = "components/core/web_json.h"
T = "test_web_json"

PUT = "\tif(writer->length < writer->size) writer->out[writer->length] = c;"
CONTROL = "\t\tif(c < 0x20 || c == 0x7F)"
QUOTE = "\t\tif(c == '\"' || c == '\\\\') put_char(writer, '\\\\');"
DIGITS = "\tdo\n\t{\n\t\tdigits[count++] = (char)('0' + number % 10);\n\t\tnumber /= 10;\n\t}\n\twhile(number != 0);"
MAGNITUDE = "\tuint32_t magnitude = number < 0 ? 0u - (uint32_t)number : (uint32_t)number;"
EMBEDDED = "\tput(writer, json == NULL || json[0] == '\\0' ? \"null\" : json);"
TOO_LONG = "\tif(writer->length >= writer->size)\n"
NUMBER = "\t\telse if(value->kind == VALUE_NUMBER && isfinite(value->number))"
FORMAT = "snprintf(number, sizeof(number), \"%.9g\", value->number == 0 ? 0.0 : value->number);"
VALUE_COMMA = "\t\tif(!first) put_char(&writer, ',');\n\t\tfirst = false;\n\t\tput_string(&writer, value->name);"
SEEN_COMMA = "\t\tif(!first) put_char(&writer, ',');\n\t\tfirst = false;\n\t\tput(&writer, \"{\\\"ssid\\\":\");"
KEY_COMMA = "\t\t\t\tif(!first) put_char(&writer, ',');\n\t\t\t\tfirst = false;\n\t\t\t\tput_string(&writer, key);"
COUNT = "\tif(profile_count > NET_PROFILES_MAX) profile_count = 0;"
PROFILE_SSID = "\t\tput_limited(&writer, profile->ssid, sizeof(profile->ssid) - 1);"
PROFILE_HOST = "\t\tput_limited(&writer, profile->host, sizeof(profile->host) - 1);"
HAS_PASSWORD = "\t\tput_bool(&writer, profile->password[0] != '\\0');"
SEEN_SSID = "\t\tput_limited(&writer, seen[i].ssid, sizeof(seen[i].ssid) - 1);"
TEXT = "\tif(!json_text(json, token, out, size)) return false;"
BYTES = "\t\tif((unsigned char)*out < 0x20) return false;"
OBJECT = "\tif(count < 0 || work[0].type != JSON_OBJECT) return false;"
PARSE = "json_parse(json, length, work, work_count);"
MEMBERS = "\tfor(int i = 0; i < work[0].size; i++)"
IS_SSID = "\t\tif(json_text_is(json, name, \"ssid\"))"
SSID = "\t\t\tif(!take_text(json, value, request->ssid, sizeof(request->ssid)) || request->ssid[0] == '\\0') return false;"
PASSWORD = "\t\t\tif(!take_text(json, value, request->password, sizeof(request->password))) return false;"
SHORT = "\t\t\tif(password_length > 0 && password_length < WPA2_PASSWORD_MIN) return false;"
HOST = "\t\t\tif(!take_text(json, value, request->host, sizeof(request->host))) return false;"
ZEROED = "\tmemset(request, 0, sizeof(*request));\n"
FORGET = "\tif(!read_request(json, length, true, &read, work, work_count)) return false;\n\n\tmemcpy(ssid, read.ssid, sizeof(read.ssid));\n\treturn true;"
BATTERY = "\t\tif(strcmp(catalog->entries[i].name, CATALOG_BATTERY) != 0) return true;"
BEFORE = "\t\tint count = p < page ? layout->pages[p].item_count : item;"
SAME_KEY = "\t\t\tif(strcmp(layout->pages[p].items[i].key, key) == 0) return true;"
UNKNOWN = "\t\t\t\tif(catalog_find(catalog, key) >= 0 || used_before(layout, p, i)) continue;"
ITEMS = "\tfor(int p = 0; p < layout->page_count; p++) items += layout->pages[p].item_count;"
LEFT = "\tput_unsigned(&writer, state == ACCESS_TICKET_WAITING ? left_s : 0);"
# GET /api/info: a release that lasts is told with 0 seconds left and with the member "lasting"
INFO_LEFT_COMMENT = ("\t// A release that lasts has no end to count down to, whatever number came with it (access.h answers the\n"
                     "\t// largest one for it)\n")
INFO_LEFT = "\tput_unsigned(&writer, info->release_lasting ? 0 : info->release_left_s);"
INFO_LASTING = "\tput(&writer, \",\\\"lasting\\\":\");\n\tput_bool(&writer, info->release_lasting);\n"
HAS_READ = "\tbool has_read = read != NULL && read[0] != '\\0';"
AGE = "\tput_unsigned(&writer, has_read ? read_age_s : 0);"

