    ("web_json_too_long_returns_length", T, F, "\t\twriter->out[0] = '\\0';\n\t\treturn -1;", "\t\twriter->out[0] = '\\0';\n\t\treturn (int)writer->length;"),
    ("web_json_too_long_returns_zero", T, F, "\t\twriter->out[0] = '\\0';\n\t\treturn -1;", "\t\twriter->out[0] = '\\0';\n\t\treturn 0;"),
